import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"0004. Serve Pages from the gh-pages branch so PR previews can live next to production","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0004-gh-pages-branch-for-previews.md","filePath":"decisions/0004-gh-pages-branch-for-previews.md"}`),a={name:`decisions/0004-gh-pages-branch-for-previews.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="_0004-serve-pages-from-the-gh-pages-branch-so-pr-previews-can-live-next-to-production" tabindex="-1" dir="auto">0004. Serve Pages from the gh-pages branch so PR previews can live next to production <a class="header-anchor" href="#_0004-serve-pages-from-the-gh-pages-branch-so-pr-previews-can-live-next-to-production" aria-label="Permalink to “0004. Serve Pages from the gh-pages branch so PR previews can live next to production”">​</a></h1><ul><li dir="auto">Status: accepted</li><li dir="auto">Date: 2026-09-22</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">The multi-agent pipeline (<code>docs/pipeline.md</code>) needs a preview URL per pull request, <code>https://&lt;owner&gt;.github.io/&lt;repo&gt;/pr-&lt;n&gt;/</code>, so a human can check an agent&#39;s work before approving. A repo has one Pages site. With the &quot;GitHub Actions&quot; source (ADR 0003), each deploy replaces the whole site, so production and previews cannot coexist.</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li dir="auto">Pages source is <strong>Deploy from a branch: <code>gh-pages</code> / (root)</strong>.</li><li dir="auto"><code>deploy.yml</code> publishes <code>site</code> at <code>/</code> and Storybook at <code>/storybook/</code>, replacing everything on <code>gh-pages</code> <strong>except</strong> <code>pr-*/</code>.</li><li dir="auto"><code>preview.yml</code> publishes each PR&#39;s <code>site</code> build (built with <code>BASE_PATH=/&lt;repo&gt;/pr-&lt;n&gt;/</code>) to <code>pr-&lt;n&gt;/</code> and deletes it when the PR closes.</li><li dir="auto">Both go through <code>.github/scripts/gh-pages-publish.sh</code>, which retries on concurrent pushes (they touch disjoint paths).</li></ul><p dir="auto">Supersedes the deployment mechanism in ADR 0003; its base-path and <code>404.html</code> decisions still hold.</p><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">One manual setting change (Settings → Pages → Source).</li><li dir="auto"><code>gh-pages</code> history grows with every deploy. Squash or recreate the branch if it gets large.</li><li dir="auto">Deep links inside a preview hit the root <code>404.html</code> (production), since Pages serves only one. Previews work from their root URL.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};